package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** What the screen shows of a period: its name and its from and to dates, both inclusive, whether
     *  it is closed, whether it is soft-closed and, once closed or soft-closed, the due-total fixed then (null while open) and each person's
     *  due-total and carried figure fixed then, by person id (empty while open), its cap on each person's open claims (null for none),
     *  each person's opening balance for it, by person id (a person missing has none), and whether it is locked. */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedTotal, Map<Long, String> closedPersonTotals, Integer cap,
            Map<Long, String> closedPersonCarried, Map<Long, String> personOpenings, boolean locked) {
        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, total.toPlainString()));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getClosedPersonCarried().forEach((id, carried) -> personCarried.put(id, carried.toPlainString()));
            Map<Long, String> openings = new TreeMap<>();
            period.getPersonOpenings().forEach((id, amount) -> openings.put(id, amount.toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedTotal() == null ? null : period.getClosedTotal().toPlainString(),
                    personTotals, period.getCap(), personCarried, openings, period.isLocked());
        }
    }

    /** A period's fields, as entered on the form; a blank cap is none. */
    public record PeriodForm(@NotBlank @Size(max = 200) String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    /** The dates monthly periods are generated between; a blank date is the sheet's today. */
    public record GenerateForm(LocalDate from, LocalDate to) {
    }

    /** The calendar year a fiscal year starts in, as entered. */
    public record GenerateFiscalYearForm(@NotNull @Min(1) @Max(9998) Integer year) {
    }

    /** The calendar year the fiscal year rolled over starts in, as entered. */
    public record RolloverForm(@NotNull @Min(1) @Max(9997) Integer year) {
    }

    /** What a rollover did: how many periods it made, and the sheet's periods now. */
    public record RolloverView(int made, List<PeriodView> periods) {
    }

    /** The calendar year whose quarters are generated, as entered. */
    public record GenerateQuartersForm(@NotNull @Min(1) @Max(9999) Integer year) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface PeriodView {
  id: number;
  name: string;
  /** The first day of the period (yyyy-mm-dd), inclusive. */
  from: string;
  /** The last day of the period (yyyy-mm-dd), inclusive. */
  to: string;
  /** Whether the period is closed: no claim dated in it can then change. */
  closed: boolean;
  /** Whether the period is soft-closed: its figures are fixed, but claims dated in it can still change. */
  softClosed: boolean;
  /** The due-total fixed when the period was closed or soft-closed, with two decimals; null while it is open. */
  closedTotal: string | null;
  /** Each person's due-total fixed when the period was closed, with two decimals, by person id; empty
   *  while it is open. A person missing from it (added after the close) has 0.00. */
  closedPersonTotals: Record<string, string>;
  /** How many OPEN or PENDING claims each person may have in the period; null for no cap. */
  cap: number | null;
  /** Each person's carried figure fixed when the period was closed or soft-closed, with two decimals, by
   *  person id; empty while it is open. A person missing from it (added after the close) has 0.00. */
  closedPersonCarried: Record<string, string>;
  /** Each person's opening balance for the period, with two decimals, by person id: part of their carried
   *  figure for it. A person missing from it has none. */
  personOpenings: Record<string, string>;
  /** Whether a steward has locked the period: a locked period cannot be reopened. */
  locked: boolean;
}

/** What pasting opening balances did: how many lines went through, and the sheet's periods now. */
export interface OpeningsView {
  added: number;
  periods: PeriodView[];
}

/** What a rollover did: how many periods it made, and the sheet's periods now. */
